def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    tokens: list of strings, each either an integer or an operator + - * /.
    Returns integer result with division truncated toward zero.
    """
    stack = []
    for t in tokens:
        if t in {"+", "-", "*", "/"}:
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                res = a + b
            elif t == '-':
                res = a - b
            elif t == '*':
                res = a * b
            else:  # division truncates toward zero
                # Use int(a / b) for truncation toward zero
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(t))
    return stack[0] if stack else 0

