            i,j = stack.pop()
            if i<0 or i>=rows or j<0 or j>=cols:
                continue
            if visited[i][j] or grid[i][j]==0:
                continue
            visited[i][j]=True
            stack.extend([(i-1,j),(i+1,j),(i,j-1),(i,j+1)])
    count=0
    for i in range(rows):
        for j in range(cols):
            if not visited[i][j] and grid[i][j]==1:
                dfs(i,j)
                count+=1
    return count

