def solve(a, x):
    """Return the leftmost index to insert x into sorted list a.
    Implements binary search manually to avoid reliance on bisect.
    """
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        # Use '<' comparison; if elements are not comparable, fallback to treat as greater
        try:
            if a[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        except Exception:
            # If comparison fails, assume a[mid] is not less than x
            hi = mid
    return lo

