import itertools, random

def solve_greedy(meetings):
    if not meetings:
        return 0
    meetings_sorted = sorted(meetings, key=lambda m: (m[1], m[0]))
    count = 0
    last_end = -10**9
    for start, end in meetings_sorted:
        if start >= last_end:
            count += 1
            last_end = end
    return count

def solve_bruteforce(meetings):
    best = 0
    n = len(meetings)
    for r in range(n+1):
        for combo in itertools.combinations(range(n), r):
