def solve(n, b):
    if b < 2 or b > 36:
        raise ValueError('Base out of range')
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    if n == 0:
        return '0'
    neg = n < 0
    n = -n if neg else n
    res = []
    while n > 0:
        n, rem = divmod(n, b)
        res.append(digits[rem])
    if neg:
