def solve(coins, amount):
    """Return minimum number of coins to make up amount using unlimited coins.
    If impossible, return -1.
    """
    # Edge cases
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Use DP array of size amount+1, initialize with a large number
    INF = amount + 1  # larger than any possible number of coins
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                # take coin c
                if dp[a - c] + 1 < dp[a]:
