def solve(n, edges):
    """Return the minimum total weight from node 0 to node n-1 in an undirected weighted graph.
    If node n-1 is unreachable, return -1. Works for n>=1.
    """
    if n == 0:
        return -1
    if n == 1:
        return 0
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for a, b, w in edges:
        if 0 <= a < n and 0 <= b < n:
            adj[a].append((b, w))
            adj[b].append((a, w))
    import heapq
    INF = 10**18
    dist = [INF] * n
    dist[0] = 0
    heap = [(0, 0)]  # (dist, node)
    while heap:
        d, u = heapq.heappop(heap)
        if d != dist[u]:
            continue
        if u == n - 1:
            # reached target with shortest distance
            return d
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    return -1

