def solve_ref(n, edges):
    # brute force all topological orders, pick smallest lexicographically
    from itertools import permutations
    # build adjacency and indegree
    adj=[set() for _ in range(n)]
    indeg=[0]*n
    for a,b in edges:
        if b not in adj[a]:
            adj[a].add(b)
            indeg[b]+=1
    best=None
    for perm in permutations(range(n)):
        # check if perm is topological
        ok=True
        pos={v:i for i,v in enumerate(perm)}
        for a in range(n):
            for b in adj[a]:
                if pos[a]>pos[b]:
                    ok=False
                    break
            if not ok:
                break
        if ok:
            if best is None or perm<best:
                best=perm
    return list(best) if best is not None else []

def solve_my(n, edges):
    from heapq import heappush, heappop
    adj=[[] for _ in range(n)]
    indeg=[0]*n
    seen=set()
    for a,b in edges:
        if (a,b) in seen:
            continue
        seen.add((a,b))
        adj[a].append(b)
        indeg[b]+=1
    heap=[]
    for i in range(n):
        if indeg[i]==0:
            heappush(heap,i)
    order=[]
    while heap:
        u=heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v]-=1
            if indeg[v]==0:
                heappush(heap,v)
    if len(order)!=n:
        return []
    return order

