def solve_my(n, edges):
    from heapq import heappush, heappop
    adj=[[] for _ in range(n)]
    indeg=[0]*n
    seen=set()
    for a,b in edges:
        if 0<=a<n and 0<=b<n:
            if (a,b) in seen:
                continue
            seen.add((a,b))
            adj[a].append(b)
            indeg[b]+=1
    heap=[]
    for i in range(n):
        if indeg[i]==0:
            heappush(heap,i)
    order=[]
    while heap:
        u=heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v]-=1
            if indeg[v]==0:
                heappush(heap,v)
    if len(order)!=n:
        return []
    return order

def brute(n, edges):
    from itertools import permutations
    adj={i:set() for i in range(n)}
    for a,b in edges:
        if 0<=a<n and 0<=b<n:
