def solve(grid):
    """Count islands (connected components of 1s) in a binary grid.
    Supports ragged grids (rows may have different lengths) and empty grids.
    """
    if not grid:
        return 0
    n = len(grid)
    # visited mirrors grid shape
    visited = [ [False]*len(row) for row in grid ]
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            # explore 4 directions, checking bounds per row length
            for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                nx, ny = x+dx, y+dy
                if 0 <= nx < n and 0 <= ny < len(grid[nx]) and not visited[nx][ny] and grid[nx][ny] == 1:
                    stack.append((nx, ny))
    count = 0
    for i, row in enumerate(grid):
        for j in range(len(row)):
            if row[j] == 1 and not visited[i][j]:
                dfs(i, j)
                count += 1
    return count

