def solve(n, edges):
    """Return the lexicographically smallest topological ordering of a directed graph.
    n: number of nodes (0 to n-1).
    edges: list of [a, b] meaning an edge a -> b.
    If the graph contains a cycle, return an empty list.
    """
    from heapq import heappush, heappop
    # Build adjacency list and indegree counts
    adj = [[] for _ in range(n)]
    indeg = [0] * n
    for a, b in edges:
        if 0 <= a < n and 0 <= b < n:
            adj[a].append(b)
            indeg[b] += 1
    # Min-heap of nodes with zero indegree
    heap = []
    for i in range(n):
        if indeg[i] == 0:
            heappush(heap, i)
    order = []
    while heap:
        u = heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heappush(heap, v)
    if len(order) != n:
        return []
    return order

